
#if DEBUG
import Foundation
extension LibraryStore {
    func seedBrandBooksIfRequested() async {
        let args = ProcessInfo.processInfo.arguments
        if args.contains("--uitest-brand-library"), books.isEmpty {
            for (index, title) in ["荒野植被", "交易沦陷", "沉溺", "暗涌"].enumerated() {
                let file = FileManager.default.temporaryDirectory.appendingPathComponent(title + ".txt")
                let text = "第一章 纸上的时光\n" + String(repeating: "这是《\(title)》的原创界面测试文字。窗外的雨下得很轻，像是不忍打扰屋内的安静。\n\n", count: 50)
                do {
                    try Data(text.utf8).write(to: file)
                    if var book = await importFile(from: file) {
                        book.importedAt = Date(timeIntervalSince1970: 1_700_000_000 - Double(index)); _ = add(book)
                        let progress = [0.72, 0.38, 1.0, 0.56][index]
                        update(position: ReadingPosition(characterOffset: Int(Double(book.characterCount) * progress), progression: progress), for: book)
                    }
                } catch { lastError = error.localizedDescription }
            }
        }
        if args.contains("--uitest-epub"), !books.contains(where: { $0.title == "封面与排版测试" }) {
            let file = FileManager.default.temporaryDirectory.appendingPathComponent("封面与排版测试.epub")
            do {
                if let data = Data(base64Encoded: "") { try data.write(to: file); _ = await importFile(from: file) }
            } catch { lastError = error.localizedDescription }
        }
    }
}
#endif
